import { MonitorClient } from 'monitor-sdk';

export interface ErrorReporter {
  capture(error: unknown, context: Record<string, unknown>): void;
}

export class MonitorErrorReporter implements ErrorReporter {
  private readonly client: MonitorClient;

  constructor(dsn: string) {
    this.client = new MonitorClient(dsn);
  }

  capture(error: unknown, context: Record<string, unknown>): void {
    this.client.captureException(error, context);
  }
}
import type { HttpRequest } from 'express-lite';
import { Hold } from './hold';
import type { HoldQueue } from './hold-queue';

export class PlaceHold {
  constructor(
    private readonly queue: HoldQueue,
    private readonly clock: () => Date,
  ) {}

  async run(req: HttpRequest): Promise<Hold> {
    const isbn = req.params.isbn;
    const cardNumber = String(req.body.cardNumber ?? '');
    if (!isbn || !cardNumber) {
      throw new Error('isbn and cardNumber are required');
    }
    const position = (await this.queue.lengthFor(isbn)) + 1;
    const hold = new Hold(isbn, cardNumber, position, this.clock());
    await this.queue.enqueue(hold);
    return hold;
  }
}
import type { Hold } from './hold';

export interface HoldQueue {
  enqueue(hold: Hold): Promise<void>;
  headFor(isbn: string): Promise<Hold | null>;
  lengthFor(isbn: string): Promise<number>;
}
import type { Hold } from '../../lending/hold';
import type { HoldQueue } from '../../lending/hold-queue';

export class InMemoryHoldQueue implements HoldQueue {
  private readonly holds = new Map<string, Hold[]>();

  async enqueue(hold: Hold): Promise<void> {
    const queue = this.holds.get(hold.isbn) ?? [];
    queue.push(hold);
    this.holds.set(hold.isbn, queue);
  }

  async headFor(isbn: string): Promise<Hold | null> {
    return this.holds.get(isbn)?.[0] ?? null;
  }

  async lengthFor(isbn: string): Promise<number> {
    return this.holds.get(isbn)?.length ?? 0;
  }
}
  }
}

